package com.aistock.prediction.explanation;
import com.fasterxml.jackson.databind.*;import java.nio.file.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
/** Explicit manual probe; excluded from default *Test suite. Reads ignored local configuration. */
class RealMaasProbe {
 @Test void realProviderProducesGroundedExplanation()throws Exception{var root=Path.of(System.getenv("MAAS_PROBE_ROOT"));var config=new HashMap<String,String>();for(var line:Files.readAllLines(root.resolve(".env"))){var at=line.indexOf('=');if(at>0)config.put(line.substring(0,at).trim(),line.substring(at+1).trim());}var m=new ObjectMapper();var sample=m.readTree(Files.readString(root.resolve("runtime/e1-real-context.json")));var facts=ExplanationFacts.build(UUID.fromString(sample.path("predictionId").asText()),sample.path("snapshot"),sample.path("model"),null,config.get("MAAS_MODEL"),m);var client=new HttpMaasClient(config.get("MAAS_CHAT_URL"),config.get("MAAS_MODEL"),config.get("MAAS_API_KEY"),true,m);JsonNode output;try{output=client.generate(facts.values());}catch(com.aistock.common.BusinessException e){throw new AssertionError("Controlled provider failure: "+e.code());}Files.writeString(root.resolve("runtime/e1-real-maas-unvalidated.json"),m.writerWithDefaultPrettyPrinter().writeValueAsString(output));var paragraphs=ExplanationTemplate.render(output,facts.values(),m);assertEquals(3,paragraphs.size());var evidence=m.createObjectNode().put("checkedAt",java.time.Instant.now().toString()).put("scope","real MaaS client and template only; not browser/session integration").put("contextHash",facts.hash());evidence.set("context",facts.context());evidence.set("paragraphs",paragraphs);Files.writeString(root.resolve("runtime/e1-real-maas-result.json"),m.writerWithDefaultPrettyPrinter().writeValueAsString(evidence));}
}
